import json, pathlib, tilelang
root = pathlib.Path(tilelang.__file__).resolve().parent
data = {"version": getattr(tilelang, "__version__", None), "path": str(root),
        "symbols": [x for x in dir(tilelang) if not x.startswith("_")]}
try:
    import tilelang.language as T
    data["language_symbols"] = [x for x in dir(T) if not x.startswith("_")]
except Exception as e: data["language_error"] = repr(e)
try:
    from tilelang import tvm
    data["tvm_version"] = tvm.__version__
    def attempt(key, fn):
        try: data[key] = fn()
        except Exception as e: data[key + "_error"] = repr(e)
    def build_info():
        if hasattr(tvm.support, "libinfo"):
            return tvm.support.libinfo()
        from tvm._ffi import libinfo
        return {"library_paths": libinfo.find_lib_path()}
    attempt("tvm_build", build_info)
    attempt("target_kinds", lambda: list(tvm.target.Target.list_kinds()))
    def global_names():
        try:
            import tvm_ffi
            return tvm_ffi.registry.list_global_func_names()
        except (ImportError, AttributeError):
            return tvm.get_global_func("runtime.ListGlobalNames")()
    attempt("ascend_global_functions", lambda: [x for x in global_names()
        if any(s in x.lower() for s in ("ascend", "npu", "cce", "pto"))])
    for key in ("target.build.tilelang_ascend", "target.build.tilelang_ascend_without_compile",
                "target.build.tilelang_pto_without_compile"):
        attempt(key, lambda key=key: tvm.get_global_func(key, allow_missing=True) is not None)
    import inspect
    attempt("compile_signature", lambda: str(inspect.signature(tilelang.compile)))
    def dialect_info():
        import tilelang.ascend.language as A
        return {"path": A.__file__, "symbols": [x for x in dir(A) if not x.startswith("_")]}
    attempt("ascend_language", dialect_info)
except Exception as e: data["tvm_error"] = repr(e)
matches = []
for p in root.rglob("*"):
    if any(s in p.name.lower() for s in ("ascend", "cann", "npu", "pto")):
        matches.append(str(p.relative_to(root)))
        if len(matches) >= 300: break
data["ascend_related_files"] = matches
data["note"] = "Symbols/targets/files are evidence only; no TileLang NPU kernel compilation was attempted."
print(json.dumps(data, indent=2, default=str))

import json, torch, torch_npu
results = {}
for dtype in (torch.float32, torch.float16, torch.bfloat16):
    try:
        x = torch.linspace(-1, 1, 1024).reshape(4, 256).to(dtype)
        a = x.to("npu:0")
        y = a * 2 + 1
        norm = a.float() * torch.rsqrt(a.float().square().mean(-1, keepdim=True) + 1e-6)
        mm = a @ a.T
        torch.npu.synchronize()
        ref = x.float() @ x.float().T
        results[str(dtype)] = {"elementwise_max_error": (y.cpu().float() - (x * 2 + 1).float()).abs().max().item(),
            "rmsnorm_finite": bool(torch.isfinite(norm).all().cpu().item()),
            "matmul_max_error": (mm.cpu().float() - ref).abs().max().item()}
    except Exception as e: results[str(dtype)] = {"error": repr(e)}
print(json.dumps(results, indent=2))
